parameters.jsCode:
const tagItems = $input.all();
const tags = tagItems.map(item => item.json?.tag_name).filter(Boolean);

const webhookData = $('Webhook Trigger (From Next.js)').first().json.body || {};
const promptNode = $('Fetch Dynamic System Prompt').first();
const rawPrompt = promptNode?.json;

let promptRow = rawPrompt;
if (Array.isArray(rawPrompt)) promptRow = rawPrompt[0] || null;
if (rawPrompt && Array.isArray(rawPrompt.data)) promptRow = rawPrompt.data[0] || null;

const dbPrompt = typeof promptRow?.bot_system_prompt === 'string'
  ? promptRow.bot_system_prompt.trim()
  : '';

const failSafePrompt = [
  'CHANNEL BUSINESS TRUTH IS NOT AVAILABLE.',
  'Use the canonical Knowledge Base for all PN product/service/company facts.',
  'Do not use memory for commercial or product claims.',
  'Do not invent price, scope, timeline, KPI, integration or policy.',
  'If channel-specific truth is required and cannot be found in canonical knowledge, hand off to a human.'
].join('\n');

return [{
  json: {
    body: webhookData,
    tags,
    systemPrompt: dbPrompt || failSafePrompt,
    dbPromptLoaded: Boolean(dbPrompt)
  }
}];

